export const crashByNo = (no) => CRASH_LIST.find((c)=>c.no===Number(no)) || {no,category:"Unknown",name:"Unknown crash",reason:"Unmapped",signal:"",section:null,sectionTitle:""};
export const CRASH_CATEGORIES = [...new Set(CRASH_LIST.map((c)=>c.category))];
function findCrashNo(pred) {
  const hit = CRASH_LIST.find(pred);
  return hit ? hit.no : null;
}
export function crashNoForApiError(err) {
  const status = Number(err?.status ?? err?.statusCode ?? 0);
  const code = String(err?.code || '');
  const msg = String(err?.message || err || '');
  if (status === 401 || code === 'UNAUTHORIZED' || /authentication required|session expired/i.test(msg))
    return findCrashNo((c) => c.category === 'API' && /^401/.test(c.name)) || CRASH_NO.UNHANDLED_REJECTION;
  if (status === 403 || code === 'FORBIDDEN' || code === 'FORBIDDEN_PATH')
    return findCrashNo((c) => c.category === 'API' && /^403/.test(c.name)) || CRASH_NO.UNHANDLED_REJECTION;
  if (status === 404 || code === 'NOT_FOUND' || /not found/i.test(msg))
    return findCrashNo((c) => c.category === 'API' && /^404/.test(c.name)) || CRASH_NO.UNHANDLED_REJECTION;
  if (status === 413 || /too large|file too large/i.test(msg))
    return findCrashNo((c) => c.category === 'API' && /413|80MB/.test(c.name)) || CRASH_NO.UNHANDLED_REJECTION;
  if (status === 429 || code === 'RATE_LIMITED' || /too many/i.test(msg))
    return findCrashNo((c) => c.category === 'API' && /429/.test(c.name)) || CRASH_NO.UNHANDLED_REJECTION;
  if (status === 409 || code === 'CONFLICT' || /already exists/i.test(msg))
    return findCrashNo((c) => c.category === 'CRUD-POST' && /409|CONFLICT/i.test(c.name))
      || findCrashNo((c) => /UNIQUE|already exists|CONFLICT/i.test(c.name) && c.category.startsWith('CRUD'))
      || findCrashNo((c) => c.category === 'API' && /409/.test(c.name))
      || CRASH_NO.UNHANDLED_REJECTION;
  if (status === 410 || code === 'EXPIRED')
    return findCrashNo((c) => /EXPIRED token|Download-410/i.test(c.category + ' ' + c.name)) || CRASH_NO.UNHANDLED_REJECTION;
  if (status >= 500)
    return findCrashNo((c) => c.category === 'API' && /^500/.test(c.name)) || CRASH_NO.UNHANDLED_REJECTION;
  if (err?.name === 'ApiError' || status >= 400) return CRASH_NO.UNHANDLED_REJECTION;
  return CRASH_NO.UNHANDLED_REJECTION;
}
